/* img_bcd_tpl.h — 自动生成，别手改（tools/mkbcdtpl.py）
 *
 * BCD 内置模板：一张「真实能启动」的 BCD，设备二进制已清零。
 * bcd.create 用它做底座，再按目标盘重写设备/路径/默认项。
 * 分两代：6.x（Vista/7）与 10.x（8/8.1/10/11）——元素表跨代兼容，
 * 但 bootmgr 的加载器路径与个别布尔项不同代有差异，分两包最稳。 */
